import json

for fname in ['preprocessor_config.json', 'tokenizer_config.json']:
    path = f'/root/autodl-tmp/models/openvla-libero-object/{fname}'
    with open(path) as f:
        data = json.load(f)

    def clean(obj):
        if isinstance(obj, dict):
            return {k.replace('openvla/openvla-7b--', ''): clean(v) for k, v in obj.items()}
        elif isinstance(obj, str):
            return obj.replace('openvla/openvla-7b--', '')
        elif isinstance(obj, list):
            return [clean(x) for x in obj]
        return obj

    data = clean(data)
    with open(path, 'w') as f:
        json.dump(data, f, indent=2)
    print(f'{fname} patched: auto_map = {data.get("auto_map", "N/A")}')
PYEOF
